class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        res = []
        for bits in product("()", repeat=2 * n):
            s = "".join(bits)
            bal = 0
            for ch in s:
                bal += 1 if ch == "(" else -1
                if bal < 0:
                    break
            if bal == 0:
                res.append(s)
        return res

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        res = []
        path = []

        def backtrack(opened, closed):
            if len(path) == 2 * n:
                res.append("".join(path))
                return
            if opened < n:
                path.append("(")
                backtrack(opened + 1, closed)
                path.pop()
            if closed < opened:
                path.append(")")
                backtrack(opened, closed + 1)
                path.pop()

        backtrack(0, 0)
        return res
